public class Main {
    // 快速求出对应数字1的位置
    public static List<Integer> countOnesAndPositions(int n) {
        List<Integer> positions = new ArrayList<>();
        int index = 0;
        while (n != 0) {
            if ((n & 1) == 1) positions.add(index);
            n >>= 1;
            index++;
        }
        return positions;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int t = scanner.nextInt();
        int k = scanner.nextInt();
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            ans[i] = scanner.nextInt();
        }
​
        int res = 0;
        for (int i = 1; i < (1 << n); i++) {
            List<Integer> pos = countOnesAndPositions(i);
            // 选取运动数量不等于k
            if (pos.size() != k) continue;
​
            int sum = 0;
            for (int index : pos) {
                sum += ans[index];
            }
            if (sum == t) res++;
        }
        System.out.println(res);
    }
}
