package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 快速求出对应数字1的位置
func countOnesAndPositions(n int) []int {
    var positions []int
    index := 0
    for n != 0 {
        if n&1 == 1 {
            positions = append(positions, index)
        }
        n >>= 1
        index++
    }
    return positions
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    line1, _ := reader.ReadString('\n')
    line2, _ := reader.ReadString('\n')
​
    parts := strings.Fields(line1)
    n, _ := strconv.Atoi(parts[0])
    t, _ := strconv.Atoi(parts[1])
    k, _ := strconv.Atoi(parts[2])
​
    numStrs := strings.Fields(line2)
    ans := make([]int, n)
    for i := 0; i < n; i++ {
        ans[i], _ = strconv.Atoi(numStrs[i])
    }
​
    res := 0
    for i := 1; i < (1 << n); i++ {
        pos := countOnesAndPositions(i)
        if len(pos) != k {
            continue
        }
        sum := 0
        for _, idx := range pos {
            sum += ans[idx]
        }
        if sum == t {
            res++
        }
    }
    fmt.Println(res)
}
